var MCD=(A,B)=>{
  const MCD=(A,B)=> A==B? A: A>B? MCD(B,A) : MCD(A,B-A);
  if(A%1!==0 || B%1!==0 ||A<0 || B<0)throw "Los números deben ser enteros positivos";
  return MCD(A,B);
};

var cheby = (x => {
  let ch=[1,x];
  const chebyr = n => n<ch.length? ch[n]: ch[n]=2*x*chebyr(n-1)-ch[n-2];
  return (xn,n ) => {
    if (xn !==x) {
      x=xn;
      ch=[1,x];
    }
    return chebyr(n);
  };
})()

